// ../case-tool/src/services/action-app-api.ts
var ACTION_APP_BATCH_SIZE = 100;
async function listActionApps() {
  const loginStatus = await getLoginStatusAsync();
  if (loginStatus.loginStatus !== "Logged in" || !loginStatus.baseUrl || !loginStatus.organizationId || !loginStatus.tenantId || !loginStatus.accessToken) {
    throw new Error("Not logged in. Run 'uip login' first.");
  }
  const all = [];
  const MAX_PAGES = 100;
  let pageNumber = 0;
  while (pageNumber < MAX_PAGES) {
    if (pageNumber === MAX_PAGES - 1) {
      logger.warn(`Fetching the last allowed page (${MAX_PAGES}). Results may be truncated.`);
    }
    const query = new URLSearchParams({
      state: "deployed",
      pageNumber: String(pageNumber),
      limit: String(ACTION_APP_BATCH_SIZE)
    });
    const url = `${loginStatus.baseUrl}/${loginStatus.organizationId}/apps_/default/api/v1/default/action-apps?${query}`;
    logger.debug(`Listing action apps with URL: ${url}`);
    const response = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${loginStatus.accessToken}`,
        "Content-Type": "application/json",
        "X-Uipath-Tenantid": loginStatus.tenantId,
        Accept: "application/json"
      }
    });
    if (!response.ok) {
      const errorText = await response.text();
      logger.error(`Error response body: ${errorText}`);
      throw new Error(`Action apps list failed: ${response.status} ${response.statusText} - ${errorText}`);
    }
    const data = await response.json();
    const page = data.deployed ?? [];
    all.push(...page);
    if (page.length < ACTION_APP_BATCH_SIZE)
      break;
    pageNumber += 1;
  }
  return all;
}

// ../case-tool/src/services/filterEngine.ts
function readField(resource, field) {
  const direct = resource[field];
  if (direct !== undefined)
    return direct;
  const cfg = resource.configuration;
  if (typeof cfg === "string") {
    try {
      const parsed = JSON.parse(cfg);
      return parsed[field];
    } catch {
      return;
    }
  }
  return;
}
function matchesKeyword(resource, keyword) {
  const lower = keyword.toLowerCase();
  const searchFields = [
    "name",
    "title",
    "displayName",
    "description",
    "category",
    "connectorKey",
    "systemName",
    "tags"
  ];
  return searchFields.some((field) => {
    const val = readField(resource, field);
    if (typeof val === "string")
      return val.toLowerCase().includes(lower);
    if (Array.isArray(val))
      return val.some((v) => typeof v === "string" && v.toLowerCase().includes(lower));
    return false;
  });
}
function matchesFilter(resource, field, operator, value) {
  const raw = readField(resource, field) ?? (field === "name" ? resource.displayName : undefined);
  const fieldValues = Array.isArray(raw) ? raw.filter((v) => typeof v === "string") : typeof raw === "string" ? [raw] : [];
  const lowerValue = value.toLowerCase();
  return fieldValues.some((v) => {
    const lv = v.toLowerCase();
    switch (operator) {
      case "equals":
        return lv === lowerValue;
      case "contains":
        return lv.includes(lowerValue);
      case "startsWith":
        return lv.startsWith(lowerValue);
      case "endsWith":
        return lv.endsWith(lowerValue);
      case "in":
        return lowerValue.split("|").map((s) => s.trim()).includes(lv);
      default:
        return false;
    }
  });
}
function searchWithFilters(resources, keyword, filters) {
  return resources.filter((resource) => {
    if (keyword && !matchesKeyword(resource, keyword))
      return false;
    if (filters && filters.filters.length > 0) {
      const filterResults = filters.filters.map(({ field, operator, value }) => matchesFilter(resource, field, operator, value));
      if (filters.logic === "AND")
        return filterResults.every(Boolean);
      return filterResults.some(Boolean);
    }
    return true;
  });
}

